out=[]
for line in ROWS.splitlines():
    name,en,vi,pro_en,pro_vi,con_en,con_vi=line.split('|')
    out.append({'name':name,'intro':{'en':en,'vi':vi},'pros':[{'en':pro_en,'vi':pro_vi}],'cons':[{'en':con_en,'vi':con_vi}]})
(Path(__file__).parent/'editorial.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(f'{len(out)} bilingual summaries written')
